def palindromeNumber(number):
    if number < 0 or number > 999:
        return False
    if number < 10:
        return True
    if number < 100:
        return number // 10 == number % 10
    return number // 100 == number % 10 and (number // 10) % 10 == (number // 10) // 10
```

